import io

from taf.vran.vdu.enb.rest.client import HttpClient
from taf.vran.vdu.enb.rest.utilities.connection_details import ConnectionDetails
from taf.vran.vdu.enb.rest.utilities.poll_status import poll_status
from taf.vran.vdu.enb.rest.exceptions import PlanValidationError


class EMSERVICEv1(HttpClient):
    def __init__(self, base_url: str, connection_details: ConnectionDetails) -> None:
        super(EMSERVICEv1, self).__init__(connection_details)
        self.base_url = base_url + "/api/emservice/v1"

    def get_plans(self) -> list:
        """
        Get list of plans available in the "Select plan" section in WebEM

        :returns: list of plans, for example:

            .. code-block:: python

                [
                   {
                      "deltaState":"noConflict",
                      "hasDefinitionErrors":false,
                      "hasRelationErrors":false,
                      "planId":"dp_33af5e62-fe16-4ae7-b345-be9fbfcaae90",
                      "planName":"Current Plan",
                      "planType":"delta",
                      "revalidationNeeded":false,
                      "revision":"1742473167115317528"
                   }
                ]
        :rtype: list(dict)
        """
        return self.send_request(method="GET", endpoint="/plans")

    def validate_staged_plan(self, plan_id: str, timeout: int = 150) -> dict:
        """
        Validates the staged plan with given plan_id and polls the validation
        status until it's completed.

        :param plan_id: plan id, get from get_plans method or ASMv1 method add_plan_to_staging
        :param timeout: timeout in seconds for the validation to complete, defaults to 150

        :returns: validation operation info, for example:

            .. code-block:: python

                {
                  "validationId": "VALIDATION_ID-1",
                  "actionId": 101,
                  "links": [
                    {
                      "rel": "self",
                      "herf": "/some/useful/links"
                    }
                  ],
                  "status": "ongoing",
                  "errorMessage": "error message"
                }
        :rtype: dict
        """
        action_id = self.send_request(
            method="POST", endpoint=f"/staged-plans/{plan_id}/actions/validations"
        )["actionId"]

        return poll_status(
            instance=self,
            endpoint=f"/staged-plans/{plan_id}/actions/validations/{action_id}",
            timeout=timeout
        )

    def get_vdu_state_data(self) -> dict:
        """
        Get information about the vDU, for example: software version, operational state, MRBTS ID.

        :returns: vDU state data, for example:

            .. code-block:: python

                {
                  "mrbtsId": "123",
                  "btsName": "some bts name",
                  "timeZone": "GMT-0700",
                  "softwareVersion": "v1.0",
                  "mcc": 20,
                  "mnc": 20,
                  "mncLength": 2,
                  "operationalState": "initializing",
                  "additionalInfo": {
                    "descriptiveName": "some descriptive name",
                    "mrbtsConfigType": "some configuration type",
                    "region": "Some region",
                    "subregion": "Some subregion",
                    "groupName": "Some group name",
                    "assignee": "Some assignee",
                    "integrationInfo": "Some integration info",
                    "targetParamInfo": "Some target parameters info"
                  },
                  "numberOfAlarms": 20,
                  "lnbtsId": "123",
                  "rnicmodDeployType": "direct FH",
                  "dnPrefix": "SubNetwork=North",
                  "managedElement": "MRBTS-123"
                }
        :rtype: dict
        """
        return self.send_request(method="GET", endpoint="/site")

    def check_validation_results(self, plan_id: str, validation_id: str) -> None:
        """
        Gets validation results and check if there are any errors.

        :param plan_id: plan id, get from get_plans method or ASMv1 method add_plan_to_staging
        :param validation_id: validation id, get from validate_staged_plan method

        :raises PlanValidationError: If there are any errors in the validation results
        """
        validation_results = self.send_request(
            method="GET", endpoint=f"/staged-plans/{plan_id}/validation-results/{validation_id}"
        )

        if validation_results["totalError"] != 0:
            raise PlanValidationError()

    def get_current_plan_id(self) -> str:
        """
        Get the "planId" field of the current plan.

        :raises ValueError: when there if no Current Plan

        :returns: plan id of the current plan
        :rtype: str
        """
        for plan in self.send_request(method="GET", endpoint="/plans"):
            if plan["planName"] == "Current Plan":
                return plan["planId"]

        raise ValueError("Could not find 'Current Plan' in the list of plans!")

    def save_plan_to_local(
        self,
        plan_id: str,
        local_dir_path: str,
        file_name: str,
        include_runtime_data: bool,
        include_delta_data: bool,
        timeout: int = 30
    ) -> str:
        """
        Saves the plan with given plan_id to local directory.

        :param plan_id: plan id
        :param local_dir_path: local directory path where the plan file will be saved
        :param file_name: name of the plan file with .xml
        :param include_runtime_data: if True, runtime data is included in the plan file
        :param include_delta_data: if True, planned changes are included in the plan file
        :param timeout: timeout in seconds for the upload to complete, defaults to 30

        :returns: path to the saved plan file
        :rtype: str
        """
        uploaded_file_name = self._upload_plan_file(
            plan_id=plan_id,
            include_runtime_data=include_runtime_data,
            include_delta_data=include_delta_data,
            timeout=timeout
        )["fileName"]

        xml_string = self.send_request(method="GET", endpoint=f"/files/{uploaded_file_name}")
        xml_file = io.StringIO(xml_string.decode("utf-8"))

        with open(f"{local_dir_path}/{file_name}", "w") as file:
            file.write(xml_file.read())

        return f"{local_dir_path}/{file_name}"

    def get_scf(
        self,
        plan_id: str,
        include_runtime_data: bool,
        include_delta_data: bool,
        timeout: int = 30
    ) -> bytes:
        """
        Get content of the plan with given plan_id

        :param plan_id: plan id
        :param bool include_runtime_data: If True, runtime data is included in the SCF file.
        :param bool include_delta_data: If True, planned changes are included in the SCF file.
        :param int timeout: Timeout for the operation. Defaults to 30 seconds.

        :returns: SCF content
        :rtype: bytes
        """
        uploaded_file_name = self._upload_plan_file(
            plan_id=plan_id,
            include_runtime_data=include_runtime_data,
            include_delta_data=include_delta_data,
            timeout=timeout
        )["fileName"]

        return self.send_request(method="GET", endpoint=f"/files/{uploaded_file_name}")

    def _upload_plan_file(
        self,
        plan_id: str,
        include_runtime_data: bool,
        include_delta_data: bool,
        timeout: int = 30
    ) -> dict:
        """
        Uploads plan file to the server and polls the upload status until it's completed.

        :param plan_id: plan id
        :param include_runtime_data: if True, runtime data is included in the plan file
        :param include_delta_data: if True, planned changes are included in the plan file
        :param int timeout: Timeout for the operation. Defaults to 30 seconds

        :return: upload operation info, for example:

            .. code-block:: python

                {
                  "fileName": "ramlPlan-1234.xml",
                  "deltaChangeOnly": true,
                  "actionId": 101,
                  "links": [
                    {
                      "rel": "self",
                      "herf": "/some/useful/links"
                    }
                  ],
                  "status": "ongoing",
                  "errorMessage": "error message"
                }
        :rtype: dict
        """
        parameters = {
            "includeDeltaData": include_delta_data,
            "deltaChangeOnly": False,
            "includeRuntimeData": include_runtime_data,
            "runtimeDataOnly": False
        }

        action_id = self.send_request(
            method="POST", endpoint=f"/delta-plans/{plan_id}/actions/uploads", json=parameters
        )["actionId"]

        return poll_status(
            instance=self,
            endpoint=f"/delta-plans/{plan_id}/actions/uploads/{action_id}",
            timeout=timeout
        )

    def get_cells_info(self) -> dict:
        """
        Get information about all cells - "created" field from GET /cells/diff response for each cell type

        :returns: information about all cells, for example:

            .. code-block:: python

                {
                   "lncel":[
                      {
                         "basicCell":{
                            "lnCelId":"123",
                            "name":"LNCEL-1",
                            "cellName":"some cell name",
                            "phyCellId":"123",
                            "eutraCelId":"123",
                            "cellTechnology":"FDD",
                            "administrativeState":"unlocked",
                            "blockingState":"Blocked",
                            "operationalState":"enabled",
                            "alarms":[
                               {
                                  "uuid":"123-456",
                                  "severity":"critical",
                                  "alarmId":7665,
                                  "alarmName":"BASE STATION TRANSMISSION ALARM",
                                  "faultId":"2016",
                                  "faultName":"BB bus reception error (summing device)"
                               }
                            ],
                            "distNames":{
                               "config":"MRBTS-1/EQM-1/APEQM-1/RMOD-1",
                               "runtime":"MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-1"
                            }
                         },
                         "band":"13 (700 c)",
                         "cellType":"very_small",
                         "expectedCellSize":"2.1km",
                         "pMax":"25 dBm",
                         "dlMimoMode":"SingleTX",
                         "maxNumActUE":"240",
                         "maxBitrateDl":"170000 kbit/s",
                         "maxBitrateUl":"110000 kbit/s",
                         "energySavingState":"notEnergySaving",
                         "availabilityStatus":"failed",
                         "usageState":"Idle",
                         "descriptiveName":"some descriptive name",
                         "cellInfo":"some cell information",
                         "cellConfigType":"some cell configuration type",
                         "targetParamInfo":"some target parameters information",
                         "channelsMapping":[
                            {
                               "rmodRId":"123",
                               "direction":"TX",
                               "antPortId":"1",
                               "antPortName":"ANT1"
                            }
                         ],
                         "actMMimo":false,
                         "actRedFreqOffset":false,
                         "actDlSlimCarrier":false,
                         "dlChRadBw":"2 MHz",
                         "dlChBw":"1.4 MHz",
                         "ulChBw":"N/A",
                         "earfcnDL":"123",
                         "earfcnUL":"123",
                         "downlinkFrequency":"123 MHz",
                         "uplinkFrequency":"123MHz",
                         "slimRfFilterDL":"Nominal",
                         "mMimoHorizontalSectorBFProf":"SingleSectorBFProf(0 degree)",
                         "lteNrDssMode":"none"
                      }
                   ]
                }
        :rtype: dict
        """
        response = self.send_request(
            method="GET", endpoint="/cells/diff", headers=self.headers.get(accept="json")
        )

        cells_info = {}
        for cell_type, cell_info in response.items():
            try:
                cells_info[cell_type] = cell_info["created"]
            except KeyError:
                pass

        return cells_info

